{"code": "const probe = String.raw`import tmp.sheaf.xif.paper.S1888D7bLocalGroupActual

noncomputable section
open LeanFormal.IUT.XiFPaper.S1888D7bLocalGroupActual
open LeanFormal.IUT.XiFPaper.S1727SectionsFPrimeActual

variable (l : PrimeGeFive)

#check S1888D7bFirstMissing l
#check S1888D7bLocalGroupFamily l
#check S1888D7bLocalGroupFamily.toSupply
#check S1888D7bFirstMissing_iff_exists_supply_firstField l
#check S1888D7bGlobalGeometry.xK_ne_S1726Orbicurve

end
`;
await tools.write({ file_path: "tmp/sheaf/xif/paper/_S1888ImportCheck.lean", content: probe });
const r = await tools.pwsh({ description: "Import-check S1888 olean", command: "lake env lean tmp/sheaf/xif/paper/_S1888ImportCheck.lean", workdir: "D:\\lean", timeoutMs: 600000 });
console.log("import check exit", r.exitCode);
console.log(r.stdout.text.slice(-4000));
console.log(r.stderr.text.slice(-2000));
const h = await tools.pwsh({ description: "Recompute source SHA256", command: "Get-FileHash 'D:\\lean\\tmp\\sheaf\\xif\\paper\\S1888D7bLocalGroupActual.lean' -Algorithm SHA256 | Format-List", workdir: "D:\\lean" });
console.log(h.stdout.text);
", "description": "Verify olean import and source hash"}

